CREATE TABLE IF NOT EXISTS admins (id uuid PRIMARY KEY, email text UNIQUE NOT NULL, password_hash text NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token_hash text PRIMARY KEY, admin_id uuid NOT NULL REFERENCES admins(id), expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS settings (id integer PRIMARY KEY CHECK(id=1), workweek_start integer NOT NULL DEFAULT 1 CHECK(workweek_start BETWEEN 1 AND 7), long_shift_hours integer NOT NULL DEFAULT 16 CHECK(long_shift_hours BETWEEN 8 AND 48), geofence_enabled boolean NOT NULL DEFAULT false, latitude double precision, longitude double precision, radius_m integer NOT NULL DEFAULT 300 CHECK(radius_m BETWEEN 50 AND 10000));
INSERT INTO settings(id) VALUES(1) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS employees (id uuid PRIMARY KEY, employee_id text UNIQUE NOT NULL, name text NOT NULL, location text NOT NULL, active boolean NOT NULL DEFAULT true, pin_hash text NOT NULL, pin_lookup text UNIQUE NOT NULL, created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE IF NOT EXISTS punches (id uuid PRIMARY KEY, employee_id uuid NOT NULL REFERENCES employees(id), type text NOT NULL CHECK(type IN ('in','lunch_out','lunch_in','out')), at timestamptz NOT NULL DEFAULT clock_timestamp(), location_check text NOT NULL DEFAULT 'not_required', created_by uuid REFERENCES admins(id), reason text);
CREATE INDEX IF NOT EXISTS punches_employee_time ON punches(employee_id,at);
CREATE TABLE IF NOT EXISTS corrections (id uuid PRIMARY KEY, punch_id uuid NOT NULL REFERENCES punches(id), original_value jsonb NOT NULL, corrected_value jsonb NOT NULL, admin_id uuid NOT NULL REFERENCES admins(id), reason text NOT NULL, at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE IF NOT EXISTS rate_limits (key text PRIMARY KEY, attempts integer NOT NULL, expires_at timestamptz NOT NULL);
CREATE OR REPLACE VIEW effective_punches AS SELECT p.id,p.employee_id,COALESCE(c.corrected_value->>'type',p.type) AS type,COALESCE((c.corrected_value->>'at')::timestamptz,p.at) AS at,p.location_check,p.created_by,p.reason FROM punches p LEFT JOIN LATERAL (SELECT corrected_value FROM corrections WHERE punch_id=p.id ORDER BY at DESC,id DESC LIMIT 1) c ON true;
